class Solution {
public:
    bool canPartition(vector<int>& nums) {
        int total = 0;
        for (int x : nums) total += x;
        if (total % 2) return false;
        int half = total / 2;
        vector<bool> can(half + 1, false);
        can[0] = true;
        for (int k = 0; k < (int)nums.size(); k++) {
            for (int s = half; s >= nums[k]; s--) {
                if (can[s - nums[k]]) can[s] = true;
            }
        }
        return can[half];
    }
};
